                                        start_name,
                                        (const gchar **)attr_names,
                                        (const gchar **)attr_values,
                                        context->user_data,
                                        &tmp_error);

  clear_attributes (context);

  if (tmp_error != NULL)
    propagate_error (context, error, tmp_error);
